// Package oneb_gen generates TypeScript models and a JSON-RPC HTTP client from
// typed oneb registrations. Generation does not execute application handlers.
package oneb_gen

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/DawnKosmos/oneb"
)

// Generate captures the methods registered by handler and writes models.ts and
// client.ts to outputDir. Pass an application's route-only method, e.g. h.Routes.
// The callback must register routes synchronously and must not retain the router.
// Only these two generated files are overwritten; other files are preserved.
func Generate(handler func(*oneb.Router), outputDir string) error {
	if handler == nil {
		return fmt.Errorf("oneb_gen: route registration handler is required")
	}
	if strings.TrimSpace(outputDir) == "" {
		return fmt.Errorf("oneb_gen: output folder is required")
	}
	operations := oneb.CaptureRoutes(handler).Operations()
	if len(operations) == 0 {
		return fmt.Errorf("oneb_gen: handler registered no RPC methods")
	}
	models := newModels()
	for _, operation := range operations {
		if _, err := models.typeOf(operation.Input); err != nil {
			return fmt.Errorf("oneb_gen: %s input: %w", operation.Name, err)
		}
		if _, err := models.typeOf(operation.Output); err != nil {
			return fmt.Errorf("oneb_gen: %s output: %w", operation.Name, err)
		}
		if operation.PositionalParams {
			if _, _, err := models.positional(operation.Input); err != nil {
				return fmt.Errorf("oneb_gen: %s positional params: %w", operation.Name, err)
			}
		}
	}
	modelSource := models.source()
	models.namespace = "Models."
	var methods strings.Builder
	for _, operation := range operations {
		input, err := models.typeOf(operation.Input)
		if err != nil {
			return err
		}
		if operation.PositionalParams {
			if tuple, ok, err := models.positional(operation.Input); err != nil {
				return fmt.Errorf("oneb_gen: %s positional params: %w", operation.Name, err)
			} else if ok {
				input += " | " + tuple
			}
		}
		output, err := models.typeOf(operation.Output)
		if err != nil {
			return err
		}
		name := strconv.Quote(operation.Name)
		fmt.Fprintf(&methods, "    [%s]: (params: %s): Promise<%s> => call<%s>(%s, params),\n", name, input, output, output, name)
	}
	clientSource := strings.Replace(clientTemplate, "// METHODS", methods.String(), 1)
	if len(models.definitions) == 0 {
		clientSource = strings.Replace(clientSource, "import type * as Models from \"./models\";\n", "", 1)
	}
	if err := os.MkdirAll(outputDir, 0o755); err != nil {
		return fmt.Errorf("oneb_gen: create output folder: %w", err)
	}
	for _, file := range []struct{ name, content string }{{"models.ts", modelSource}, {"client.ts", clientSource}} {
		if err := os.WriteFile(filepath.Join(outputDir, file.name), []byte(file.content), 0o644); err != nil {
			return fmt.Errorf("oneb_gen: write %s: %w", file.name, err)
		}
	}
	return nil
}

const clientTemplate = `// Code generated by oneb_gen. DO NOT EDIT.

import type * as Models from "./models";

export class RpcError extends Error {
  constructor(public readonly code: number, message: string, public readonly data?: unknown) {
    super(message);
    this.name = "RpcError";
  }
}

/** Pass the complete RPC endpoint URL, e.g. "/rpc". Options may include headers and an AbortSignal. */
export function createClient(url: string, options: RequestInit = {}) {
  let nextID = 0;

  async function call<O>(method: string, params: unknown): Promise<O> {
    const id = ++nextID;
    const headers = new Headers(options.headers);
    headers.set("Content-Type", "application/json");
    const response = await fetch(url, {
      ...options,
      method: "POST",
      headers,
      body: JSON.stringify({ jsonrpc: "2.0", method, params, id }),
    });
    if (!response.ok) {
      throw new Error("JSON-RPC HTTP error: " + response.status);
    }
    const body: unknown = await response.json();
    if (typeof body !== "object" || body === null || Array.isArray(body)) {
      throw new Error("Invalid JSON-RPC response");
    }
    const reply = body as Record<string, unknown>;
    const hasResult = Object.prototype.hasOwnProperty.call(reply, "result");
    const hasError = Object.prototype.hasOwnProperty.call(reply, "error");
    if (reply.jsonrpc !== "2.0" || reply.id !== id || hasResult === hasError) {
      throw new Error("Invalid JSON-RPC response");
    }
    if (hasError) {
      if (typeof reply.error !== "object" || reply.error === null || Array.isArray(reply.error)) {
        throw new Error("Invalid JSON-RPC error");
      }
      const error = reply.error as Record<string, unknown>;
      if (typeof error.code !== "number" || typeof error.message !== "string") {
        throw new Error("Invalid JSON-RPC error");
      }
      throw new RpcError(error.code, error.message, error.data);
    }
    return reply.result as O;
  }

  return {
// METHODS
  };
}
`
